// Parse and validate input address
const input = $input.first().json;
const direccion = input.query?.direccion || input.direccion || input.address || '';

if (!direccion || typeof direccion !== 'string' || direccion.trim().length === 0) {
  throw new Error('No se proporcionó una dirección válida');
}

function normalizeAddress(addr) {
  let clean = String(addr).trim();

  clean = clean.replace(/^(la\s+dirección\s+es\s*:?-?\s*)/i, '');
  clean = clean.replace(/\s+/g, ' ').trim();

  if (!/españa|spain/i.test(clean)) {
    clean = clean.replace(/[,.\s]+$/, '') + ', España';
  }

  return clean.trim();
}

const normalized = normalizeAddress(direccion);

console.log('Input address:', direccion);
console.log('Normalized:', normalized);

return {
  json: {
    direccion: normalized,
    direccion_original: direccion.trim(),
    timestamp: new Date().toISOString(),
    workflow_version: 'v1.0'
  }
};

// Geocode address using multiple providers
const direccion = $input.first().json.direccion;
const direccionOriginal = $input.first().json.direccion_original;

const results = [];

async function fetchJSON(url, headers = {}) {
  try {
    const defaultHeaders = {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
      'Accept': 'application/json'
    };

    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 15000,
      headers: { ...defaultHeaders, ...headers },
      json: true
    });

    return response;
  } catch (error) {
    console.error(`Fetch error for ${url}:`, error.message);
    return null;
  }
}

function isValidSpainCoords(lat, lon) {
  return lat >= 27.5 && lat <= 43.8 && lon >= -18.5 && lon <= 4.5;
}

function extractProvincia(state, county) {
  if (!state && !county) return null;

  const stateNorm = (state || '').toLowerCase().trim();
  const countyNorm = (county || '').toLowerCase().trim();

  const provincias = [
    'madrid', 'barcelona', 'valencia', 'sevilla', 'málaga', 'malaga',
    'murcia', 'alicante', 'córdoba', 'cordoba', 'valladolid', 'coruña',
    'coruna', 'granada', 'oviedo', 'bilbao', 'zaragoza', 'cádiz', 'cadiz',
    'toledo', 'navarra', 'cantabria', 'rioja', 'asturias',
    'tarragona', 'badajoz', 'lleida', 'caceres', 'leon', 'burgos',
    'guipúzcoa', 'guipuzcoa', 'vizcaya', 'jaen', 'almeria', 'almería',
    'huelva', 'palmas', 'tenerife'
  ];

  for (const prov of provincias) {
    if (stateNorm.includes(prov) || countyNorm.includes(prov)) {
      return prov;
    }
  }

  const comunidadMap = {
    'comunidad de madrid': 'madrid',
    'cataluña': 'barcelona',
    'catalunya': 'barcelona',
    'comunidad valenciana': 'valencia',
    'comunitat valenciana': 'valencia',
    'andalucía': 'sevilla',
    'andalucia': 'sevilla',
    'país vasco': 'vizcaya',
    'euskadi': 'vizcaya',
    'galicia': 'coruña',
    'castilla y león': 'valladolid',
    'castilla-la mancha': 'toledo',
    'aragón': 'zaragoza',
    'aragon': 'zaragoza',
    'extremadura': 'badajoz',
    'asturias': 'asturias',
    'murcia': 'murcia',
    'navarra': 'navarra',
    'cantabria': 'cantabria',
    'la rioja': 'rioja',
    'islas baleares': 'baleares',
    'illes balears': 'baleares',
    'canarias': 'tenerife'
  };

  for (const [comunidad, provincia] of Object.entries(comunidadMap)) {
    if (stateNorm.includes(comunidad)) {
      return provincia;
    }
  }

  return stateNorm || countyNorm || null;
}

function extractHouseNumber(address) {
  if (!address) return null;
  const patterns = [
    / (\d+)\s*(?:bis|ter|[abc])? /i,
    /nº\s*(\d+)/i,
    /n\.\s*(\d+)/i,
    /número\s*(\d+)/i
  ];

  for (const pattern of patterns) {
    const match = address.match(pattern);
    if (match) return match[1];
  }

  return null;
}

function parseStreetName(street) {
  if (!street) return { type: null, name: null };

  const viaTypes = [
    'calle', 'avenida', 'plaza', 'paseo', 'carretera', 'camino',
    'glorieta', 'ronda', 'travesía', 'travesia', 'callejón', 'callejon',
    'boulevard', 'parque', 'jardín', 'jardin', 'poligono', 'polígono'
  ];

  const streetLower = street.toLowerCase().trim();

  for (const tipo of viaTypes) {
    const patterns = [
      new RegExp(`^${tipo}\s+(.+)$`, 'i'),
      new RegExp(`^${tipo[0]}\.\s+(.+)$`, 'i'),
      new RegExp(`^${tipo}\/(.+)$`, 'i')
    ];

    for (const pattern of patterns) {
      const match = streetLower.match(pattern);
      if (match) {
        return {
          type: tipo,
          name: match[1].trim()
        };
      }
    }
  }

  return { type: 'calle', name: street };
}

console.log('=== GEOCODING START ===');
console.log('Address:', direccion);

try {
  const url = `https://nominatim.openstreetmap.org/search?format=json&limit=10&addressdetails=1&countrycodes=es&q=${encodeURIComponent(direccion)}`;
  const data = await fetchJSON(url);

  if (Array.isArray(data) && data.length > 0) {
    for (const item of data) {
      const lat = parseFloat(item.lat);
      const lon = parseFloat(item.lon);

      if (!isValidSpainCoords(lat, lon)) continue;

      const addr = item.address || {};
      const streetInfo = parseStreetName(addr.road || addr.pedestrian || addr.footway);
      const provincia = extractProvincia(addr.state, addr.county) || addr.province;

      results.push({
        original: direccionOriginal,
        full_address: item.display_name,
        street_type: streetInfo.type,
        street_name: streetInfo.name,
        house_number: addr.house_number || extractHouseNumber(direccionOriginal),
        postcode: addr.postcode || null,
        city: addr.city || addr.town || addr.village || addr.municipality || null,
        county: addr.county || null,
        provincia: provincia,
        state: addr.state || null,
        country: 'España',
        lat: lat.toFixed(7),
        lon: lon.toFixed(7),
        source: 'nominatim',
        importance: parseFloat(item.importance || 0),
        place_rank: parseInt(item.place_rank || 999)
      });
    }
  }
} catch (error) {
  console.error('Nominatim error:', error.message);
}

try {
  const url = `https://photon.komoot.io/api/?q=${encodeURIComponent(direccion)}&limit=10&lang=es`;
  const data = await fetchJSON(url);

  if (data?.features && Array.isArray(data.features)) {
    for (const feature of data.features) {
      if (!feature?.geometry?.coordinates) continue;

      const lon = parseFloat(feature.geometry.coordinates[0]);
      const lat = parseFloat(feature.geometry.coordinates[1]);

      if (!isValidSpainCoords(lat, lon)) continue;

      const props = feature.properties || {};
      const streetInfo = parseStreetName(props.street || props.name);
      const provincia = extractProvincia(props.state, props.county);

      const isDuplicate = results.some(r =>
        Math.abs(parseFloat(r.lat) - lat) < 0.0001 &&
        Math.abs(parseFloat(r.lon) - lon) < 0.0001
      );

      if (!isDuplicate) {
        results.push({
          original: direccionOriginal,
          full_address: props.name || direccion,
          street_type: streetInfo.type,
          street_name: streetInfo.name,
          house_number: props.housenumber || extractHouseNumber(direccionOriginal),
          postcode: props.postcode || null,
          city: props.city || props.town || props.village || null,
          county: props.county || null,
          provincia: provincia,
          state: props.state || null,
          country: 'España',
          lat: lat.toFixed(7),
          lon: lon.toFixed(7),
          source: 'photon',
          importance: 0.7,
          place_rank: 500
        });
      }
    }
  }
} catch (error) {
  console.error('Photon error:', error.message);
}

if (results.length === 0) {
  throw new Error(`No se pudo geocodificar la dirección: ${direccion}`);
}

results.forEach(r => {
  r.score = ((r.importance || 0) * 10) + (r.house_number ? 5 : 0) + (r.postcode ? 3 : 0) + (r.provincia ? 2 : 0) + (r.city ? 1 : 0) - ((r.place_rank || 999) / 100);
});

results.sort((a, b) => b.score - a.score);

console.log('=== GEOCODING COMPLETE ===');
console.log(`Total results: ${results.length}`);
console.log(`Best result: ${results[0].full_address}`);

return results.map(addr => ({
  json: {
    direccion_original: direccionOriginal,
    parsed_address: addr,
    timestamp: new Date().toISOString()
  }
}));

// Find cadastral reference using Catastro services
const parsedAddress = $input.first().json.parsed_address;
const direccionOriginal = $input.first().json.direccion_original;

if (!parsedAddress) {
  throw new Error('No parsed address available');
}

const lat = parseFloat(parsedAddress.lat);
const lon = parseFloat(parsedAddress.lon);

if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
  throw new Error('Invalid coordinates');
}

const allReferences = [];

async function httpGet(url, accept = 'application/xml') {
  try {
    console.log(`Fetching: ${url.substring(0, 100)}...`);

    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 20000,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        'Accept': accept,
        'Accept-Language': 'es-ES,es;q=0.9',
        'Referer': 'https://www1.sedecatastro.gob.es/'
      },
      encoding: 'utf8'
    });

    return response;
  } catch (error) {
    console.error(`HTTP error: ${error.message}`);
    return null;
  }
}

function parseXMLValue(xml, tagName) {
  const patterns = [
    new RegExp(`<${tagName}[^>]*>([^<]*)</${tagName}>`, 'i'),
    new RegExp(`<${tagName}[^>]*>\s*<!\[CDATA\[([^\]]+)\]\]>\s*</${tagName}>`, 'i')
  ];

  for (const pattern of patterns) {
    const match = String(xml || '').match(pattern);
    if (match) return match[1].trim();
  }

  return null;
}

function extractBuildingRC(rc) {
  if (!rc || typeof rc !== 'string') return null;
  const clean = rc.trim().toUpperCase().replace(/[^0-9A-Z]/g, '');
  return clean.length >= 14 ? clean.substring(0, 14) : null;
}

function extractAllRC(text) {
  const pattern = / ([0-9]{7}[A-Z0-9]{7,}) /g;
  const matches = String(text || '').match(pattern) || [];
  return [...new Set(matches.map(extractBuildingRC).filter(Boolean))];
}

console.log('=== CATASTRO REFERENCE SEARCH ===');
console.log('Coordinates:', lat, lon);
console.log('Address:', parsedAddress.full_address);

try {
  const srs = 'EPSG:4326';
  const url = `https://ovc.catastro.meh.es/ovcservweb/ovcswlocalizacionrc/ovccoordenadas.asmx/Consulta_RCCOOR?SRS=${srs}&Coordenada_X=${lon}&Coordenada_Y=${lat}`;
  const xml = await httpGet(url, 'application/xml,text/xml,*/*');

  if (xml) {
    const errorCode = parseXMLValue(xml, 'err') || parseXMLValue(xml, 'codigo');
    const errorMsg = parseXMLValue(xml, 'des') || parseXMLValue(xml, 'descripcion');

    if (!errorCode || errorCode === '0') {
      const rc1 = parseXMLValue(xml, 'rc') || parseXMLValue(xml, 'refcat');
      const pc1 = parseXMLValue(xml, 'pc1') || parseXMLValue(xml, 'pc');
      const rcList = extractAllRC(xml);

      for (const rc of [rc1, pc1, ...rcList]) {
        const buildingRC = extractBuildingRC(rc);
        if (buildingRC && !allReferences.some(r => r.ref === buildingRC)) {
          allReferences.push({
            ref: buildingRC,
            source: 'Consulta_RCCOOR',
            method: 'coordinates',
            priority: 1
          });
        }
      }
    } else {
      console.log(`Consulta_RCCOOR error: ${errorCode} - ${errorMsg}`);
    }
  }
} catch (error) {
  console.error('RCCOOR error:', error.message);
}

if (allReferences.length === 0) {
  const distances = [50, 100, 200];

  for (const dist of distances) {
    try {
      const url = `https://ovc.catastro.meh.es/ovcservweb/ovcswlocalizacionrc/ovccoordenadas.asmx/Consulta_RCCOOR_Distancia?SRS=EPSG:4326&Coordenada_X=${lon}&Coordenada_Y=${lat}&Distancia=${dist}`;
      const xml = await httpGet(url, 'application/xml,text/xml,*/*');

      if (xml) {
        const rcList = extractAllRC(xml);

        if (rcList.length > 0) {
          for (const rc of rcList) {
            if (!allReferences.some(r => r.ref === rc)) {
              allReferences.push({
                ref: rc,
                source: `RCCOOR_Distancia_${dist}m`,
                method: 'nearby',
                priority: 2
              });
            }
          }
          break;
        }
      }
    } catch (error) {
      console.error(`RCCOOR_Distancia ${dist} error:`, error.message);
    }
  }
}

if (allReferences.length === 0 && parsedAddress.street_name && parsedAddress.city) {
  try {
    const tipoViaMap = {
      'calle': 'CL', 'avenida': 'AV', 'plaza': 'PZ', 'paseo': 'PS',
      'carretera': 'CR', 'camino': 'CM', 'glorieta': 'GL', 'ronda': 'RD',
      'travesia': 'TV', 'travesía': 'TV'
    };

    const tipoVia = tipoViaMap[parsedAddress.street_type?.toLowerCase()] || 'CL';
    const provincia = parsedAddress.provincia || '';
    const municipio = parsedAddress.city || '';
    const nombreVia = parsedAddress.street_name || '';
    const numero = parsedAddress.house_number || '';

    const url = `https://ovc.catastro.meh.es/ovcservweb/OVCSWLocalizacionRC/OVCCallejero.asmx/Consulta_DNPPP?Provincia=${encodeURIComponent(provincia.toUpperCase())}&Municipio=${encodeURIComponent(municipio.toUpperCase())}&TipoVia=${tipoVia}&NombreVia=${encodeURIComponent(nombreVia.toUpperCase())}&Numero=${numero}`;

    const xml = await httpGet(url, 'application/xml,text/xml,*/*');

    if (xml) {
      const rcList = extractAllRC(xml);

      for (const rc of rcList) {
        if (!allReferences.some(r => r.ref === rc)) {
          allReferences.push({
            ref: rc,
            source: 'Consulta_DNPPP',
            method: 'address',
            priority: 3
          });
        }
      }
    }
  } catch (error) {
    console.error('DNPPP error:', error.message);
  }
}

if (allReferences.length === 0) {
  const pads = [0.0005, 0.001, 0.002];

  for (const pad of pads) {
    try {
      const bbox = `${lat - pad},${lon - pad},${lat + pad},${lon + pad}`;
      const url = `https://ovc.catastro.meh.es/cartografia/INSPIRE/spadgcwms.aspx?service=WMS&request=GetFeatureInfo&version=1.3.0&CRS=EPSG:4326&LAYERS=CP.CadastralParcel&QUERY_LAYERS=CP.CadastralParcel&WIDTH=101&HEIGHT=101&I=50&J=50&BBOX=${bbox}&INFO_FORMAT=text/plain`;
      const response = await httpGet(url, 'text/plain,*/*');

      if (response) {
        const lines = String(response).split(/?
/);

        for (const line of lines) {
          const parts = line.split('	');
          if (parts.length >= 2 && /nationalCadastralReference/i.test(parts[0])) {
            const rc = extractBuildingRC(parts[1]);
            if (rc && !allReferences.some(r => r.ref === rc)) {
              allReferences.push({
                ref: rc,
                source: `WMS_${pad}`,
                method: 'wms',
                priority: 4
              });
            }
          }
        }

        if (allReferences.length > 0) break;
      }
    } catch (error) {
      console.error(`WMS ${pad} error:`, error.message);
    }
  }
}

if (allReferences.length === 0) {
  try {
    const pad = 0.01;
    const bbox = `${lat - pad},${lon - pad},${lat + pad},${lon + pad}`;
    const url = `https://ovc.catastro.meh.es/INSPIRE/wfsBU.aspx?service=WFS&version=2.0.0&request=GetFeature&storedquery_id=GetBuildingsByBBOX&BBOX=${bbox},EPSG:4326`;
    const gml = await httpGet(url, 'application/xml,application/gml+xml,*/*');

    if (gml) {
      const matches = String(gml).match(/ES\.SDGC\.BU\.([0-9A-Z]{14,})/gi) || [];

      for (const match of matches) {
        const rc = extractBuildingRC(match.replace(/^ES\.SDGC\.BU\./i, ''));
        if (rc && !allReferences.some(r => r.ref === rc)) {
          allReferences.push({
            ref: rc,
            source: 'WFS_BBOX',
            method: 'wfs',
            priority: 5
          });
        }
      }
    }
  } catch (error) {
    console.error('WFS error:', error.message);
  }
}

if (allReferences.length === 0) {
  return [{
    json: {
      success: false,
      error: 'No se encontró referencia catastral',
      direccion: direccionOriginal,
      parsed_address: parsedAddress,
      methods_attempted: [
        'Consulta_RCCOOR',
        'Consulta_RCCOOR_Distancia',
        'Consulta_DNPPP',
        'WMS_GetFeatureInfo',
        'WFS_BBOX'
      ],
      timestamp: new Date().toISOString()
    }
  }];
}

const uniqueRefs = new Map();
for (const ref of allReferences) {
  if (!uniqueRefs.has(ref.ref) || uniqueRefs.get(ref.ref).priority > ref.priority) {
    uniqueRefs.set(ref.ref, ref);
  }
}

const sorted = Array.from(uniqueRefs.values()).sort((a, b) => a.priority - b.priority);

return sorted.map(ref => ({
  json: {
    direccion: direccionOriginal,
    parsed_address: parsedAddress,
    referencia_catastral: ref.ref,
    lat: parsedAddress.lat,
    lon: parsedAddress.lon,
    rc_source: ref.source,
    rc_method: ref.method,
    priority: ref.priority,
    success: true
  }
}));

// Get detailed cadastral data for a reference
const refCat = $input.first().json.referencia_catastral;
const lat = parseFloat($input.first().json.lat);
const lon = parseFloat($input.first().json.lon);
const direccion = $input.first().json.direccion;
const parsedAddress = $input.first().json.parsed_address;

if (!refCat) {
  throw new Error('No cadastral reference available');
}

const datos = {
  success: true,
  direccion,
  referencia_catastral: refCat,
  lat: lat.toFixed(7),
  lon: lon.toFixed(7),
  parsed_address: parsedAddress
};

const dataSources = [];

async function httpGet(url, accept = 'application/xml') {
  try {
    console.log(`Fetching: ${url.substring(0, 80)}...`);

    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 20000,
      headers: {
        'User-Agent': 'Mozilla/5.0 n8n-catastro/4.0',
        'Accept': accept,
        'Referer': 'https://www1.sedecatastro.gob.es/'
      },
      encoding: 'utf8'
    });

    return response;
  } catch (error) {
    console.error(`HTTP error: ${error.message}`);
    return null;
  }
}

function parseXMLValue(xml, tagName) {
  const patterns = [
    new RegExp(`<${tagName}[^>]*>([^<]*)</${tagName}>`, 'i'),
    new RegExp(`<${tagName}[^>]*>\s*<!\[CDATA\[([^\]]+)\]\]>\s*</${tagName}>`, 'i')
  ];

  for (const pattern of patterns) {
    const match = String(xml || '').match(pattern);
    if (match && match[1]) return match[1].trim();
  }

  return null;
}

function parseHTMLTable(html) {
  const data = {};
  const str = String(html || '');

  const rowRegex = /<tr[^>]*>\s*<td[^>]*>([\s\S]*?)<\/td>\s*<td[^>]*>([\s\S]*?)<\/td>\s*<\/tr>/gi;
  const stripHTML = (s) => String(s || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&[a-z]+;/gi, '')
    .replace(/\s+/g, ' ')
    .trim();

  let match;
  while ((match = rowRegex.exec(str))) {
    const key = stripHTML(match[1]);
    const value = stripHTML(match[2]);
    if (key && value) data[key] = value;
  }

  const inspireMatch = str.match(/ES\.SDGC\.BU\.([0-9A-Z]+)/i);
  if (inspireMatch) data.inspireId = 'ES.SDGC.BU.' + inspireMatch[1];

  return data;
}

function toNumber(value) {
  if (value == null) return null;
  const cleaned = String(value)
    .replace(/[^0-9.,]/g, '')
    .replace(',', '.');
  const num = parseFloat(cleaned);
  return Number.isFinite(num) ? num : null;
}

console.log('=== FETCHING CATASTRO DATA ===');
console.log('Reference:', refCat);

try {
  const url = `https://ovc.catastro.meh.es/ovcservweb/ovcswlocalizacionrc/ovccoordenadas.asmx/Consulta_CPMRC?Provincia=&Municipio=&RC=${refCat}`;
  const xml = await httpGet(url, 'application/xml,text/xml,*/*');

  if (xml) {
    dataSources.push({ source: 'Consulta_CPMRC' });

    const coordX = parseXMLValue(xml, 'xcen') || parseXMLValue(xml, 'coordenada_x');
    const coordY = parseXMLValue(xml, 'ycen') || parseXMLValue(xml, 'coordenada_y');
    const address = parseXMLValue(xml, 'ldt') || parseXMLValue(xml, 'direccion');
    const provincia = parseXMLValue(xml, 'np') || parseXMLValue(xml, 'provincia');
    const municipio = parseXMLValue(xml, 'nm') || parseXMLValue(xml, 'municipio');

    if (coordX && coordY) {
      datos.coord_x_catastro = parseFloat(coordX);
      datos.coord_y_catastro = parseFloat(coordY);
    }
    if (address) datos.direccion_catastro = address;
    if (provincia) datos.provincia = provincia;
    if (municipio) datos.municipio = municipio;
  }
} catch (error) {
  console.error('CPMRC error:', error.message);
}

try {
  const url = `https://ovc.catastro.meh.es/ovcservweb/OVCSWLocalizacionRC/OVCCallejero.asmx/Consulta_DNPRC?Provincia=&Municipio=&RC=${refCat}`;
  const xml = await httpGet(url, 'application/xml,text/xml,*/*');

  if (xml) {
    dataSources.push({ source: 'Consulta_DNPRC' });

    const supConst = parseXMLValue(xml, 'sfc') || parseXMLValue(xml, 'sc');
    const supParcela = parseXMLValue(xml, 'sfs') || parseXMLValue(xml, 'sp');
    const clase = parseXMLValue(xml, 'locs') || parseXMLValue(xml, 'clase');
    const uso = parseXMLValue(xml, 'lous') || parseXMLValue(xml, 'uso');
    const ano = parseXMLValue(xml, 'ant') || parseXMLValue(xml, 'anio');

    if (supConst) datos.superficie_construida_catastro = Math.round(toNumber(supConst));
    if (supParcela) datos.superficie_parcela_m2 = Math.round(toNumber(supParcela));
    if (clase) datos.clase = clase;
    if (uso) datos.uso = uso;
    if (ano) datos.ano_construccion = ano;
  }
} catch (error) {
  console.error('DNPRC error:', error.message);
}

try {
  const pad = 0.00055;
