async function httpGet(url, accept = 'application/xml', method = 'GET', body = null) {
  try {
    const options = {
      method,
      url,
      timeout: 25000,
      headers: {
        'User-Agent': 'Mozilla/5.0 n8n-catastro/4.0',
        'Accept': accept,
        'Referer': 'https://ovc.catastro.meh.es/'
      },
      encoding: 'utf8'
    };

    if (body) {
      options.body = body;
      options.headers['Content-Type'] = 'text/plain';
    }

    return await this.helpers.httpRequest(options);
  } catch (error) {
    console.error(`HTTP error: ${error.message}`);
    return null;
  }
}

function parsePosList(gml) {
  const polygons = [];
  const regex = /<gml:posList[^>]*>([\s\S]*?)<\/gml:posList>/gi;

  let match;
  while ((match = regex.exec(String(gml || '')))) {
    const coords = match[1]
      .trim()
      .split(/\s+/)
      .map(Number)
      .filter(Number.isFinite);

    if (coords.length < 6) continue;

    const step = coords.length % 3 === 0 ? 3 : 2;
    const points = [];

    for (let i = 0; i + (step - 1) < coords.length; i += step) {
      points.push([coords[i], coords[i + 1]]);
    }

    if (points.length >= 3) {
      polygons.push(points);
    }
  }

  return polygons;
}

function calculateXY(points) {
  let A = 0;
  let P = 0;

  for (let i = 0; i < points.length; i++) {
    const [x1, y1] = points[i];
    const [x2, y2] = points[(i + 1) % points.length];
    A += x1 * y2 - x2 * y1;
    P += Math.hypot(x2 - x1, y2 - y1);
  }

  return {
    area: Math.abs(A) / 2,
    perimeter: P
  };
}

function projectUTM(lon, lat) {
  const a = 6378137;
  const f = 1 / 298.257222101;
  const k0 = 0.9996;
  const e = Math.sqrt(2 * f - f * f);
  const lon0 = -3 * Math.PI / 180;

  const lonRad = lon * Math.PI / 180;
  const latRad = lat * Math.PI / 180;

  const N = a / Math.sqrt(1 - e * e * Math.sin(latRad) ** 2);
  const T = Math.tan(latRad) ** 2;
  const C = (e * e / (1 - e * e)) * Math.cos(latRad) ** 2;
  const A = (lonRad - lon0) * Math.cos(latRad);

  const M = a * (
    (1 - e * e / 4 - 3 * e ** 4 / 64 - 5 * e ** 6 / 256) * latRad -
    (3 * e * e / 8 + 3 * e ** 4 / 32 + 45 * e ** 6 / 1024) * Math.sin(2 * latRad) +
    (15 * e ** 4 / 256 + 45 * e ** 6 / 1024) * Math.sin(4 * latRad) -
    (35 * e ** 6 / 3072) * Math.sin(6 * latRad)
  );

  const x = k0 * N * (
    A + (1 - T + C) * A ** 3 / 6 +
    (5 - 18 * T + T ** 2 + 72 * C - 58 * (e ** 2 / (1 - e ** 2))) * A ** 5 / 120
  ) + 500000;

  const y = k0 * (
    M + N * Math.tan(latRad) * (
      A ** 2 / 2 +
      (5 - T + 9 * C + 4 * C ** 2) * A ** 4 / 24 +
      (61 - 58 * T + T ** 2 + 600 * C - 330 * (e ** 2 / (1 - e ** 2))) * A ** 6 / 720
    )
  );

  return { x, y };
}

function calculateLatLon(points) {
  const projected = points.map(p => projectUTM(p.lon, p.lat));

  let A = 0;
  let P = 0;

  for (let i = 0; i < projected.length; i++) {
    const p1 = projected[i];
    const p2 = projected[(i + 1) % projected.length];
    A += p1.x * p2.y - p2.x * p1.y;
    P += Math.hypot(p2.x - p1.x, p2.y - p1.y);
  }

  return {
    area: Math.abs(A) / 2,
    perimeter: P
  };
}

