if (!(area > 0)) {
  try {
    const query = `[out:json][timeout:20];
      way(around:100,${lat},${lon})["building"];
      (._;>;);
      out;`;

    const response = await httpGet('https://overpass-api.de/api/interpreter', 'application/json', 'POST', query);

    if (response) {
      const data = typeof response === 'string' ? JSON.parse(response) : response;

      if (data?.elements) {
        const nodes = new Map();
        let building = null;

        for (const el of data.elements) {
          if (el.type === 'node') {
            nodes.set(el.id, { lat: el.lat, lon: el.lon });
          } else if (el.type === 'way' && el.tags?.building && !building) {
            building = el;
          }
        }

        if (building?.nodes) {
          const points = building.nodes
            .map(id => nodes.get(id))
            .filter(Boolean);

          if (points.length >= 3) {
            const geom = calculateLatLon(points);
            area = geom.area;
            perimeter = geom.perimeter;
            geometrySources.push({ source: 'OpenStreetMap' });
          }
        }
      }
    }
  } catch (error) {
    console.error('OSM error:', error.message);
  }
}

