if ((!datos.alturas || datos.alturas === 0) && datos.superficie_oficial_m2 && datos.superficie_construida_m2) {
  const oficialArea = datos.superficie_oficial_m2;
  const footprintArea = datos.superficie_construida_m2;

  if (footprintArea > 10) {
    const ratio = oficialArea / footprintArea;

    if (ratio >= 0.7 && ratio <= 50) {
      datos.alturas = Math.max(1, Math.round(ratio));
      datos.alturas_estimadas = true;
      floorsSources.push({
        source: 'calculated_ratio',
        value: datos.alturas,
        formula: `${oficialArea} / ${footprintArea} = ${ratio.toFixed(2)}`
      });
    }
  }
}

if ((!datos.alturas || datos.alturas === 0) && datos.numero_viviendas && datos.numero_viviendas > 0) {
  const dwellings = datos.numero_viviendas;
  let estimated = 2;

  if (dwellings === 1) {
    estimated = 2;
  } else if (dwellings <= 4) {
    estimated = dwellings;
  } else if (dwellings <= 8) {
    estimated = Math.ceil(dwellings / 2);
  } else if (dwellings <= 20) {
    estimated = Math.ceil(dwellings / 3);
  } else {
    estimated = Math.min(10, Math.ceil(dwellings / 4));
  }

  datos.alturas = estimated;
  datos.alturas_estimadas = true;
  floorsSources.push({
    source: 'estimated_dwellings',
    value: estimated,
    dwellings
  });
}

if (!datos.alturas || datos.alturas === 0) {
  datos.alturas = 2;
  datos.alturas_estimadas = true;
  floorsSources.push({
    source: 'default',
    value: 2
  });
}

datos.alturas = Math.max(1, Math.min(50, datos.alturas));

if (floorsSources.length > 0) {
