// Deduplicate and rank results
const items = $input.all();

if (items.length === 0) {
  throw new Error('No results to process');
}

const grouped = new Map();

for (const item of items) {
  const data = item.json;

  if (!data.referencia_catastral) continue;

  const key = `${parseFloat(data.lat).toFixed(5)}_${parseFloat(data.lon).toFixed(5)}`;

  if (!grouped.has(key)) {
    grouped.set(key, []);
  }

  grouped.get(key).push(data);
}

const results = [];

for (const [key, group] of grouped.entries()) {
  group.sort((a, b) => (a.priority || 999) - (b.priority || 999));

  const best = { ...group[0] };

  if (group.length > 1) {
    best.alternative_references = group.slice(1).map(g => ({
      referencia_catastral: g.referencia_catastral,
      source: g.rc_source,
      priority: g.priority
    }));
  }

  results.push(best);
}

return results.map(r => ({ json: r }));

